#!/usr/bin/env python3
"""Apply the profile's light/dark palette to SVGs generated by Platane/snk."""

import re
import sys
from pathlib import Path
from xml.etree import ElementTree

PALETTES = {
    "github-snake.svg": {
        "background": "#eaf3f4", "cb": "#c9dbe3", "cs": "#a93265",
        "s1": "#92345f", "s2": "#7b355e", "s3": "#633c5d",
        "ce": "#d7e5eb", "c0": "#d7e5eb", "c1": "#aec7df",
        "c2": "#719fc7", "c3": "#2796ae", "c4": "#3bad82", "c5": "#bc862b",
    },
    "github-snake-dark.svg": {
        "background": "#101526", "cb": "#30415a", "cs": "#ff8db4",
        "s1": "#f574a8", "s2": "#dc619d", "s3": "#bc528e",
        "ce": "#263650", "c0": "#263650", "c1": "#4e6daa",
        "c2": "#407fad", "c3": "#28b1bf", "c4": "#6ad4a0", "c5": "#f6ca69",
    },
}

REDUCED_MOTION = (
    "@media (prefers-reduced-motion: reduce)"
    "{.c,.u,.s{animation:none!important}}"
)
TAIL_STYLE = ".s.s1{fill:var(--s1)}.s.s2{fill:var(--s2)}.s.s3{fill:var(--s3)}"
SURFACE_RE = re.compile(r'<rect data-snake-surface="true"[^>]*/>')
ROOT_RE = re.compile(r":root\{[^}]*\}")
RECT_RE = re.compile(r'<rect [^>]*/>')
CLASS_RE = re.compile(r'class="([^"]+)"')
FILL_RE = re.compile(r'fill="[^"]*"')


def style_snake(svg, palette):
    """Keep the real contribution cells and snake keyframes untouched."""
    variables = ";".join(f"--{key}:{value}" for key, value in palette.items() if key != "background")
    svg, count = ROOT_RE.subn(":root{" + variables + "}", svg, count=1)
    if count != 1 or "<style>" not in svg or "</style>" not in svg:
        raise ValueError("Expected a Platane/snk SVG with one palette block")
    svg = svg.replace('viewBox="-16 -32 880 192" width="880" height="192"',
                      'viewBox="-24 -40 896 208" width="896" height="208"', 1)
    if 'viewBox="-24 -40 896 208"' not in svg:
        raise ValueError("Unexpected snake canvas dimensions")
    svg = svg.replace(
        "<desc>Generated with https://github.com/Platane/snk</desc>",
        "<title>Serpiente de contribuciones de Doker367</title>"
        "<desc>La serpiente recorre las contribuciones reales de GitHub. "
        "Animación generada con Platane/snk.</desc>",
        1,
    )
    svg = SURFACE_RE.sub("", svg)
    if REDUCED_MOTION not in svg:
        svg = svg.replace("</style>", REDUCED_MOTION + "</style>", 1)
    if TAIL_STYLE not in svg:
        svg = svg.replace("</style>", TAIL_STYLE + "</style>", 1)
    surface = (
        '<rect data-snake-surface="true" x="-24" y="-40" '
        'width="896" height="208" rx="16" '
        f'fill="{palette["background"]}"/>'
    )
    svg = svg.replace("</style>", "</style>" + surface, 1)

    # SVG viewers that ignore CSS variables still display the real activity.
    levels = dict(re.findall(r'\.c\.c([0-9a-f]+)\{fill:var\(--c([0-5])\)', svg))
    progress_levels = dict(re.findall(r'\.u\.u([0-9]+)\{fill:var\(--c([0-5])\)', svg))
    if not levels:
        raise ValueError("Snake SVG has no contribution-level styles")

    def fallback_fill(match):
        rect = match.group(0)
        found = CLASS_RE.search(rect)
        if not found:
            return rect
        classes = found.group(1).split()
        if classes[0] == "c":
            color = palette["c" + levels.get(classes[-1][1:], "0")] if len(classes) > 1 else palette["ce"]
        elif classes[0] == "u":
            color = palette["c" + progress_levels.get(classes[-1][1:], "0")]
        elif classes[0] == "s":
            color = palette.get(classes[-1], palette["cs"])
        else:
            return rect
        if FILL_RE.search(rect):
            return FILL_RE.sub(f'fill="{color}"', rect, count=1)
        return rect[:-2] + f' fill="{color}"/>'

    svg = RECT_RE.sub(fallback_fill, svg)
    ElementTree.fromstring(svg)
    return svg


def main(directory):
    for name, palette in PALETTES.items():
        path = directory / name
        original = path.read_text(encoding="utf-8")
        styled = style_snake(original, palette)
        path.write_text(styled, encoding="utf-8")
        print(f"Styled {path} without altering its animation")


if __name__ == "__main__":
    main(Path(sys.argv[1]) if len(sys.argv) > 1 else Path("dist"))
